// Package conformance holds the real-PostgreSQL conformance suite for the
// durable State API (internal/state). Every test here runs against the
// database named by AHP_TEST_DATABASE_URL; a missing URL fails the test
// instead of skipping it, because a skipped check must never be reported as
// a passed one.
//
// The suite never drops, truncates or rewrites shared tables: each test works
// in a scope freshly generated by contracts.NewID and only ever touches the
// rows it inserted itself.
package conformance

import (
	"context"
	"encoding/json"
	"os"
	"strconv"
	"testing"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/ahp-platform/ahp/internal/state"
	"github.com/ahp-platform/ahp/pkg/contracts"
)

// EnvDatabaseURL is the only way this suite locates PostgreSQL.
const EnvDatabaseURL = "AHP_TEST_DATABASE_URL"

// testStore returns a context, a dedicated pool and a migrated Store bound to
// a brand-new (tenant, deployment, subject) scope, plus a cleanup that removes
// exactly the fixture rows the test inserts under that scope.
func testStore(t *testing.T) (context.Context, *pgxpool.Pool, *state.Store, contracts.Scope) {
	t.Helper()

	dsn := os.Getenv(EnvDatabaseURL)
	if dsn == "" {
		t.Fatalf("%s is not set: the State API conformance suite runs only against a real PostgreSQL", EnvDatabaseURL)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
	t.Cleanup(cancel)

	pool, err := pgxpool.New(ctx, dsn)
	if err != nil {
		t.Fatalf("conformance: create pgx pool: %v", err)
	}
	t.Cleanup(pool.Close)
	if err := pool.Ping(ctx); err != nil {
		t.Fatalf("conformance: ping PostgreSQL at %s: %v", EnvDatabaseURL, err)
	}

	store := state.New(pool)
	if err := store.Migrate(ctx); err != nil {
		t.Fatalf("conformance: state migrate: %v", err)
	}

	scope := contracts.Scope{
		Tenant:     "tnt-" + contracts.NewID(),
		Deployment: "dep-" + contracts.NewID(),
		Subject:    "usr-" + contracts.NewID(),
	}
	t.Cleanup(func() { cleanupScope(t, pool, scope) })
	return ctx, pool, store, scope
}

// cleanupScope deletes only the threads of one generated scope; the runs go
// with them through the ON DELETE CASCADE foreign key.
func cleanupScope(t *testing.T, pool *pgxpool.Pool, scope contracts.Scope) {
	t.Helper()
	cleanupCtx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
	defer cancel()
	tag, err := pool.Exec(cleanupCtx,
		`DELETE FROM ahp_state.threads WHERE tenant = $1 AND deployment = $2 AND subject = $3`,
		scope.Tenant, scope.Deployment, scope.Subject)
	if err != nil {
		t.Errorf("conformance: cleanup fixture rows of scope %s/%s/%s: %v",
			scope.Tenant, scope.Deployment, scope.Subject, err)
		return
	}
	if tag.RowsAffected() > 0 {
		t.Logf("conformance: cleaned %d fixture thread(s) of scope %s", tag.RowsAffected(), scope.Tenant)
	}
}

// newThread creates a thread with a fresh context id and idempotency key.
func newThread(t *testing.T, ctx context.Context, store *state.Store, scope contracts.Scope) state.Thread {
	t.Helper()
	th, err := store.CreateThread(ctx, scope, "ctx-"+contracts.NewID(), "thread-key-"+contracts.NewID())
	if err != nil {
		t.Fatalf("conformance: CreateThread: %v", err)
	}
	return th
}

// createRun creates one run with a fresh idempotency key and the given payload.
func createRun(t *testing.T, ctx context.Context, store *state.Store, scope contracts.Scope,
	threadID, taskID string, payload json.RawMessage) state.Run {
	t.Helper()
	r, err := store.CreateRun(ctx, scope, threadID, taskID, "run-key-"+contracts.NewID(), payload)
	if err != nil {
		t.Fatalf("conformance: CreateRun(%s): %v", taskID, err)
	}
	return r
}

// claim loops until a lease is granted or the deadline passes. Concurrency
// tests must not depend on wall-clock timings: a claim only returns a lease
// once the database actually made one available.
func claim(t *testing.T, ctx context.Context, store *state.Store, scope contracts.Scope,
	worker string, ttl time.Duration, wait time.Duration) *state.Lease {
	t.Helper()
	deadline := time.Now().Add(wait)
	for {
		l, err := store.ClaimRun(ctx, scope.Tenant, scope.Deployment, worker, ttl)
		if err != nil {
			t.Fatalf("conformance: ClaimRun(%s): %v", worker, err)
		}
		if l != nil {
			return l
		}
		if time.Now().After(deadline) {
			return nil
		}
		select {
		case <-ctx.Done():
			t.Fatalf("conformance: ClaimRun(%s): %v", worker, ctx.Err())
		case <-time.After(10 * time.Millisecond):
		}
	}
}

// claimEmpty asserts that nothing is claimable right now. The settle delay
// lets queued work from earlier assertions land first.
func claimEmpty(t *testing.T, ctx context.Context, store *state.Store, scope contracts.Scope, worker string) {
	t.Helper()
	time.Sleep(150 * time.Millisecond)
	if l := claim(t, ctx, store, scope, worker, time.Minute, 300*time.Millisecond); l != nil {
		t.Fatalf("conformance: expected no claimable run, but claimed run %s (status %s)", l.Run.ID, l.Run.Status)
	}
}

// expireLease forces the thread lease of runID to have expired one second ago
// in database time. The UPDATE is keyed by thread id and current lease holder,
// so it can only ever age the lease row this very run holds.
func expireLease(t *testing.T, ctx context.Context, pool *pgxpool.Pool, threadID, runID string) {
	t.Helper()
	tag, err := pool.Exec(ctx, `
		UPDATE ahp_state.threads
		   SET lease_expires = clock_timestamp() - interval '1 second'
		 WHERE id = $1 AND lease_run_id = $2`, threadID, runID)
	if err != nil {
		t.Fatalf("conformance: expire lease of thread %s (run %s): %v", threadID, runID, err)
	}
	if tag.RowsAffected() != 1 {
		t.Fatalf("conformance: expiring the lease of thread %s touched %d rows, want exactly 1",
			threadID, tag.RowsAffected())
	}
}

// mustCode asserts err carries the expected stable contract code.
func mustCode(t *testing.T, err error, code string, what string) {
	t.Helper()
	if err == nil {
		t.Fatalf("conformance: %s: want error %s, got nil", what, code)
	}
	if got := contracts.Code(err); got != code {
		t.Fatalf("conformance: %s: want code %s, got %q (err: %v)", what, code, got, err)
	}
}

// mustNoErr fails the test when err is non-nil, naming the operation.
func mustNoErr(t *testing.T, err error, what string) {
	t.Helper()
	if err != nil {
		t.Fatalf("conformance: %s: %v", what, err)
	}
}

// sameRun reports whether two views describe the very same run record.
func sameRun(a, b state.Run) bool { return a.ID == b.ID }

// jsonPayload returns a small unique JSON document for one label.
func jsonPayload(t *testing.T, label string) json.RawMessage {
	t.Helper()
	raw, err := json.Marshal(map[string]any{"label": label, "n": 1})
	if err != nil {
		t.Fatalf("conformance: encode payload: %v", err)
	}
	return raw
}

// leaseOf is a compact lease description for failure messages.
func leaseOf(l *state.Lease) string {
	if l == nil {
		return "<no lease>"
	}
	return "thread=" + l.Thread.ID + " run=" + l.Run.ID + " worker=" + l.Worker +
		" epoch=" + strconv.FormatInt(l.Epoch, 10)
}
